#include "experience.h"

#define EX_MAGIC0 'A'
#define EX_MAGIC1 'I'
#define EX_MAGIC2 'E'
#define EX_MAGIC3 'X'
#define EX_MAGIC4 '0'
#define EX_MAGIC5 '7'

typedef struct ExperienceHeader { BYTE magic[8]; DWORD schema; DWORD count; DWORD record_size; } ExperienceHeader;

static void ze(void* p0,unsigned long long n){unsigned char* p=(unsigned char*)p0;unsigned long long i;for(i=0;i<n;i++)p[i]=0;}
static int wl_e(const WCHAR* s){int n=0;while(s&&s[n])n++;return n;}
static void wc_e(WCHAR* d,int cap,const WCHAR* s){int i=0;if(!d||cap<=0)return;while(s&&s[i]&&i<cap-1){d[i]=s[i];i++;}d[i]=0;}
static void wa_e(WCHAR* d,int cap,const WCHAR* s){int n=wl_e(d),i=0;while(s&&s[i]&&n<cap-1)d[n++]=s[i++];d[n]=0;}
static int weq_e(const u16* a,const u16* b){int i=0;if(!a||!b)return 0;while(a[i]&&b[i]&&a[i]==b[i])i++;return a[i]==b[i];}
static WCHAR loww(WCHAR c){if(c>=L'A'&&c<=L'Z')return c+(L'a'-L'A');return c;}
static u64 hash_rule(const u16* s){u64 h=1469598103934665603ULL;int i=0;WCHAR c;while(s&&s[i]){c=loww((WCHAR)s[i++]);if(c==L' '||c==L'\r'||c==L'\n'||c==L'\t'||c==L'，'||c==L'。'||c==L','||c==L'.')continue;h^=(u64)(unsigned int)c;h*=1099511628211ULL;}return h?h:1ULL;}
static void int_e(int v,WCHAR* out,int cap){WCHAR t[32];unsigned int x;int n=0,i=0;if(v<0){if(i<cap-1)out[i++]=L'-';x=(unsigned int)(-(long long)v);}else x=(unsigned int)v;if(x==0)t[n++]=L'0';while(x&&n<31){t[n++]=(WCHAR)(L'0'+x%10);x/=10;}while(n&&i<cap-1)out[i++]=t[--n];out[i]=0;}
static void hex64_e(u64 v,WCHAR* out,int cap){static const WCHAR h[]=L"0123456789ABCDEF";int i,p=0;if(cap<17){if(cap>0)out[0]=0;return;}for(i=15;i>=0;i--)out[p++]=h[(v>>(i*4))&15];out[p]=0;}
static void now_e(u16* out,int cap){SYSTEMTIME t;WCHAR n[16];GetLocalTime(&t);out[0]=0;int_e(t.wYear,n,16);wa_e((WCHAR*)out,cap,n);wa_e((WCHAR*)out,cap,L"-");if(t.wMonth<10)wa_e((WCHAR*)out,cap,L"0");int_e(t.wMonth,n,16);wa_e((WCHAR*)out,cap,n);wa_e((WCHAR*)out,cap,L"-");if(t.wDay<10)wa_e((WCHAR*)out,cap,L"0");int_e(t.wDay,n,16);wa_e((WCHAR*)out,cap,n);wa_e((WCHAR*)out,cap,L" ");if(t.wHour<10)wa_e((WCHAR*)out,cap,L"0");int_e(t.wHour,n,16);wa_e((WCHAR*)out,cap,n);wa_e((WCHAR*)out,cap,L":");if(t.wMinute<10)wa_e((WCHAR*)out,cap,L"0");int_e(t.wMinute,n,16);wa_e((WCHAR*)out,cap,n);wa_e((WCHAR*)out,cap,L":");if(t.wSecond<10)wa_e((WCHAR*)out,cap,L"0");int_e(t.wSecond,n,16);wa_e((WCHAR*)out,cap,n);}
static int header_ok_e(const ExperienceHeader* h){return h&&h->magic[0]==EX_MAGIC0&&h->magic[1]==EX_MAGIC1&&h->magic[2]==EX_MAGIC2&&h->magic[3]==EX_MAGIC3&&h->magic[4]==EX_MAGIC4&&h->magic[5]==EX_MAGIC5&&h->schema==1&&h->record_size==sizeof(ExperienceRecord);}
static void make_header_e(ExperienceHeader* h){ze(h,sizeof(*h));h->magic[0]=EX_MAGIC0;h->magic[1]=EX_MAGIC1;h->magic[2]=EX_MAGIC2;h->magic[3]=EX_MAGIC3;h->magic[4]=EX_MAGIC4;h->magic[5]=EX_MAGIC5;h->schema=1;h->record_size=sizeof(ExperienceRecord);}
static int source_same(const ExperienceRecord* e,const AIReviewRecord* r){return e&&r&&e->source_horizon==r->horizon&&weq_e(e->source_prediction_id,r->prediction_id);}
static const FundRecord* find_fund(const FundStore* store,const u16* code){int i;if(!store)return NULL;for(i=0;i<store->count;i++)if(weq_e(store->funds[i].code,code))return &store->funds[i];return NULL;}
static int eligible(const AIReviewRecord* r){if(!r||!r->reusable_rule[0]||!r->lesson[0])return 0;if(!r->snapshot_loaded||r->lucky_hit)return 0;if(r->reasoning_quality==REVIEW_QUALITY_UNSUPPORTED)return 0;if(r->evidence_score<55||r->review_confidence<55)return 0;if(r->grade==REVIEW_GRADE_D)return 0;return 1;}
static int initial_score(const AIReviewRecord* r){int s=45+r->evidence_score/5+r->review_confidence/10;if(r->grade==REVIEW_GRADE_A)s+=10;else if(r->grade==REVIEW_GRADE_B)s+=4;else if(r->grade==REVIEW_GRADE_C)s-=2;if(s>95)s=95;if(s<35)s=35;return s;}
static int status_for_score(int s){return s>=60?EXPERIENCE_STATUS_ACTIVE:(s>=30?EXPERIENCE_STATUS_OBSERVE:EXPERIENCE_STATUS_RETIRED);}
static int type_for_review(const AIReviewRecord* r){if(r->direction_correct&&r->reasoning_quality==REVIEW_QUALITY_SUPPORTED)return EXPERIENCE_TYPE_SUCCESS;if(!r->direction_correct)return EXPERIENCE_TYPE_FAILURE;return EXPERIENCE_TYPE_CAUTION;}
static void make_id(ExperienceRecord* e){WCHAR hx[24],n[16];e->experience_id[0]=0;wa_e((WCHAR*)e->experience_id,ARCHIVE_ID_CAP,L"EXP-");hex64_e(e->rule_hash,hx,24);wa_e((WCHAR*)e->experience_id,ARCHIVE_ID_CAP,hx);wa_e((WCHAR*)e->experience_id,ARCHIVE_ID_CAP,L"-");int_e(e->source_horizon,n,16);wa_e((WCHAR*)e->experience_id,ARCHIVE_ID_CAP,n);}
static int append_e(const StorageContext* st,const ExperienceRecord* e){HANDLE h;ExperienceHeader hd;DWORD n=0,pos;if(!st||!e)return 0;h=CreateFileW(st->experience_path,GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ,NULL,OPEN_ALWAYS,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE)return 0;pos=SetFilePointer(h,0,NULL,FILE_END);if(pos==0){make_header_e(&hd);if(!WriteFile(h,&hd,sizeof(hd),&n,NULL)||n!=sizeof(hd)){CloseHandle(h);return 0;}}else{SetFilePointer(h,0,NULL,FILE_BEGIN);if(!ReadFile(h,&hd,sizeof(hd),&n,NULL)||n!=sizeof(hd)||!header_ok_e(&hd)){CloseHandle(h);return 0;}}SetFilePointer(h,0,NULL,FILE_END);if(!WriteFile(h,e,sizeof(*e),&n,NULL)||n!=sizeof(*e)){CloseHandle(h);return 0;}hd.count++;SetFilePointer(h,0,NULL,FILE_BEGIN);if(!WriteFile(h,&hd,sizeof(hd),&n,NULL)||n!=sizeof(hd)){CloseHandle(h);return 0;}CloseHandle(h);return 1;}
static int scan_source_or_rule(const StorageContext* st,const AIReviewRecord* r,u64 rh,DWORD* source_idx,DWORD* rule_idx,ExperienceRecord* rule_rec){HANDLE h;ExperienceHeader hd;ExperienceRecord e;DWORD n=0,i;if(source_idx)*source_idx=0xFFFFFFFFu;if(rule_idx)*rule_idx=0xFFFFFFFFu;h=CreateFileW(st->experience_path,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE)return 1;if(!ReadFile(h,&hd,sizeof(hd),&n,NULL)||n!=sizeof(hd)||!header_ok_e(&hd)){CloseHandle(h);return 0;}for(i=0;i<hd.count;i++){if(!ReadFile(h,&e,sizeof(e),&n,NULL)||n!=sizeof(e))break;if(source_same(&e,r)){if(source_idx)*source_idx=i;CloseHandle(h);return 1;}if(rule_idx&&*rule_idx==0xFFFFFFFFu&&e.rule_hash==rh){*rule_idx=i;if(rule_rec)*rule_rec=e;}}CloseHandle(h);return 1;}
static int rewrite_at(const StorageContext* st,DWORD idx,const ExperienceRecord* e){HANDLE h;ExperienceHeader hd;DWORD n=0,pos;h=CreateFileW(st->experience_path,GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE)return 0;if(!ReadFile(h,&hd,sizeof(hd),&n,NULL)||n!=sizeof(hd)||!header_ok_e(&hd)||idx>=hd.count){CloseHandle(h);return 0;}pos=(DWORD)sizeof(hd)+idx*(DWORD)sizeof(*e);SetFilePointer(h,(LONG)pos,NULL,FILE_BEGIN);if(!WriteFile(h,e,sizeof(*e),&n,NULL)||n!=sizeof(*e)){CloseHandle(h);return 0;}CloseHandle(h);return 1;}

int experience_sync_reviews(const StorageContext* st,const FundStore* store,int* scanned_reviews,int* created,int* merged,int* rejected){ReviewStats rs;AIReviewRecord* rr;int n,i,sc=0,cr=0,mg=0,rj=0,cap;if(scanned_reviews)*scanned_reviews=0;if(created)*created=0;if(merged)*merged=0;if(rejected)*rejected=0;if(!st)return 0;if(!review_get_stats(st,&rs)||rs.review_count<=0){storage_log_ex(st,L"INFO",L"EXPERIENCE_EXTRACT",NULL,L"reviews=0，暂无AI复盘可提取经验");return 0;}cap=rs.review_count>4096?4096:rs.review_count;rr=(AIReviewRecord*)HeapAlloc(GetProcessHeap(),HEAP_ZERO_MEMORY,sizeof(AIReviewRecord)*cap);if(!rr)return 0;n=review_load_latest(st,rr,cap);for(i=0;i<n;i++){u64 rh;DWORD si=0xFFFFFFFFu,ri=0xFFFFFFFFu;ExperienceRecord olde,e;WCHAR m[320],x[32];const FundRecord* f;sc++;if(!eligible(&rr[i])){rj++;continue;}rh=hash_rule(rr[i].reusable_rule);ze(&olde,sizeof(olde));if(!scan_source_or_rule(st,&rr[i],rh,&si,&ri,&olde)){storage_log_ex(st,L"ERROR",L"EXPERIENCE_EXTRACT",rr[i].fund_code,L"经验库文件结构异常，停止本轮提取");break;}if(si!=0xFFFFFFFFu)continue;if(ri!=0xFFFFFFFFu){int ns=olde.score+5;if(ns>95)ns=95;olde.score=ns;olde.status=status_for_score(ns);olde.verified_count++;olde.evidence_score=(olde.evidence_score+rr[i].evidence_score)/2;olde.review_confidence=(olde.review_confidence+rr[i].review_confidence)/2;now_e(olde.last_verified_time,FUND_TIME_CAP);if(rewrite_at(st,ri,&olde)){m[0]=0;wa_e(m,320,L"MERGED id=");wa_e(m,320,(WCHAR*)olde.experience_id);wa_e(m,320,L" score=");int_e(olde.score,x,32);wa_e(m,320,x);wa_e(m,320,L" verified=");int_e(olde.verified_count,x,32);wa_e(m,320,x);storage_log_ex(st,L"INFO",L"EXPERIENCE_EXTRACT",rr[i].fund_code,m);mg++;}continue;}ze(&e,sizeof(e));e.rule_hash=rh;wc_e((WCHAR*)e.source_prediction_id,ARCHIVE_ID_CAP,(WCHAR*)rr[i].prediction_id);wc_e((WCHAR*)e.fund_code,FUND_CODE_CAP,(WCHAR*)rr[i].fund_code);wc_e((WCHAR*)e.fund_name,FUND_NAME_CAP,(WCHAR*)rr[i].fund_name);f=find_fund(store,rr[i].fund_code);if(f)wc_e((WCHAR*)e.fund_type,FUND_META_CAP,(WCHAR*)f->fund_type);e.source_horizon=rr[i].horizon;e.source_grade=rr[i].grade;e.experience_type=type_for_review(&rr[i]);e.score=initial_score(&rr[i]);e.status=status_for_score(e.score);e.evidence_score=rr[i].evidence_score;e.review_confidence=rr[i].review_confidence;e.verified_count=1;e.usage_count=0;now_e(e.created_time,FUND_TIME_CAP);wc_e((WCHAR*)e.last_verified_time,FUND_TIME_CAP,(WCHAR*)e.created_time);wc_e((WCHAR*)e.lesson,EXPERIENCE_TEXT_CAP,(WCHAR*)rr[i].lesson);wc_e((WCHAR*)e.reusable_rule,EXPERIENCE_TEXT_CAP,(WCHAR*)rr[i].reusable_rule);make_id(&e);if(append_e(st,&e)){m[0]=0;wa_e(m,320,L"CREATED id=");wa_e(m,320,(WCHAR*)e.experience_id);wa_e(m,320,L" type=");wa_e(m,320,experience_type_name(e.experience_type));wa_e(m,320,L" score=");int_e(e.score,x,32);wa_e(m,320,x);storage_log_ex(st,L"INFO",L"EXPERIENCE_SAVE",e.fund_code,m);cr++;}else storage_log_ex(st,L"ERROR",L"EXPERIENCE_SAVE",rr[i].fund_code,L"experience_store_v1.bin写入失败");}HeapFree(GetProcessHeap(),0,rr);if(scanned_reviews)*scanned_reviews=sc;if(created)*created=cr;if(merged)*merged=mg;if(rejected)*rejected=rj;{WCHAR m[256],x[32];m[0]=0;wa_e(m,256,L"DONE scanned=");int_e(sc,x,32);wa_e(m,256,x);wa_e(m,256,L" created=");int_e(cr,x,32);wa_e(m,256,x);wa_e(m,256,L" merged=");int_e(mg,x,32);wa_e(m,256,x);wa_e(m,256,L" rejected=");int_e(rj,x,32);wa_e(m,256,x);storage_log_ex(st,L"INFO",L"EXPERIENCE_EXTRACT",NULL,m);}return cr+mg;}

static int load_latest_generic_e(const StorageContext* st,ExperienceRecord* out,int max){HANDLE h;ExperienceHeader hd;DWORD n=0,start,count,pos;if(!st||!out||max<=0)return 0;h=CreateFileW(st->experience_path,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE)return 0;if(!ReadFile(h,&hd,sizeof(hd),&n,NULL)||n!=sizeof(hd)||!header_ok_e(&hd)){CloseHandle(h);return 0;}count=hd.count<(DWORD)max?hd.count:(DWORD)max;start=hd.count-count;pos=(DWORD)sizeof(hd)+start*(DWORD)sizeof(ExperienceRecord);SetFilePointer(h,(LONG)pos,NULL,FILE_BEGIN);if(count&&(!ReadFile(h,out,count*(DWORD)sizeof(ExperienceRecord),&n,NULL)||n!=count*(DWORD)sizeof(ExperienceRecord))){CloseHandle(h);return 0;}CloseHandle(h);return (int)count;}
int experience_load_latest(const StorageContext* st,ExperienceRecord* out,int max_records){return load_latest_generic_e(st,out,max_records);}

static int score_match(const ExperienceRecord* e,const FundRecord* f){int s=e->score;if(weq_e(e->fund_code,f->code))s+=30;else if(e->fund_type[0]&&f->fund_type[0]&&weq_e(e->fund_type,f->fund_type))s+=18;else return -1;if(e->experience_type==EXPERIENCE_TYPE_FAILURE)s+=3;if(e->verified_count>1)s+=e->verified_count>5?10:e->verified_count*2;return s;}
int experience_search(const StorageContext* st,const FundRecord* fund,ExperienceRecord* out,int max_records){HANDLE h;ExperienceHeader hd;ExperienceRecord e;DWORD n=0,i;int count=0;if(!st||!fund||!out||max_records<=0)return 0;h=CreateFileW(st->experience_path,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE)return 0;if(!ReadFile(h,&hd,sizeof(hd),&n,NULL)||n!=sizeof(hd)||!header_ok_e(&hd)){CloseHandle(h);return 0;}for(i=0;i<hd.count;i++){int ms,j;if(!ReadFile(h,&e,sizeof(e),&n,NULL)||n!=sizeof(e))break;if(e.status!=EXPERIENCE_STATUS_ACTIVE||e.score<60)continue;ms=score_match(&e,fund);if(ms<0)continue;if(count<max_records){out[count++]=e;}else{int worst=0,wscore=score_match(&out[0],fund);for(j=1;j<count;j++){int x=score_match(&out[j],fund);if(x<wscore){worst=j;wscore=x;}}if(ms>wscore)out[worst]=e;}}CloseHandle(h);if(count>1){int a,b;for(a=0;a<count-1;a++)for(b=a+1;b<count;b++)if(score_match(&out[b],fund)>score_match(&out[a],fund)){ExperienceRecord t=out[a];out[a]=out[b];out[b]=t;}}return count;}

int experience_get_stats(const StorageContext* st,ExperienceStats* out){HANDLE h;ExperienceHeader hd;ExperienceRecord e;DWORD n=0,i;if(!st||!out)return 0;ze(out,sizeof(*out));h=CreateFileW(st->experience_path,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE)return 1;if(!ReadFile(h,&hd,sizeof(hd),&n,NULL)||n!=sizeof(hd)||!header_ok_e(&hd)){CloseHandle(h);return 0;}for(i=0;i<hd.count;i++){if(!ReadFile(h,&e,sizeof(e),&n,NULL)||n!=sizeof(e))break;out->total_count++;if(e.status==EXPERIENCE_STATUS_ACTIVE)out->active_count++;else if(e.status==EXPERIENCE_STATUS_OBSERVE)out->observe_count++;else out->retired_count++;if(e.experience_type==EXPERIENCE_TYPE_SUCCESS)out->success_count++;if(e.experience_type==EXPERIENCE_TYPE_FAILURE)out->failure_count++;}CloseHandle(h);return 1;}

static int utf8_append_w(char* out,int cap,int* p,const WCHAR* w){int need,i;char* tmp;if(!out||!p||!w)return 0;need=WideCharToMultiByte(CP_UTF8,0,w,-1,NULL,0,NULL,NULL);if(need<=0)return 0;tmp=(char*)HeapAlloc(GetProcessHeap(),0,(SIZE_T)need);if(!tmp)return 0;WideCharToMultiByte(CP_UTF8,0,w,-1,tmp,need,NULL,NULL);for(i=0;tmp[i]&&*p<cap-1;i++){unsigned char c=(unsigned char)tmp[i];if(c=='"'||c=='\\'){if(*p+2>=cap){HeapFree(GetProcessHeap(),0,tmp);return 0;}out[(*p)++]='\\';out[(*p)++]=(char)c;}else if(c=='\r'||c=='\n'||c=='\t'){out[(*p)++]=' ';}else out[(*p)++]=(char)c;}out[*p]=0;HeapFree(GetProcessHeap(),0,tmp);return 1;}
static int ascii_append(char* out,int cap,int* p,const char* s){int i=0;while(s&&s[i]){if(*p>=cap-1)return 0;out[(*p)++]=s[i++];}out[*p]=0;return 1;}
static int int_append(char* out,int cap,int* p,int v){char t[32];unsigned int x;int n=0;if(v<0){if(!ascii_append(out,cap,p,"-"))return 0;x=(unsigned int)(-(long long)v);}else x=(unsigned int)v;if(x==0)t[n++]='0';while(x&&n<31){t[n++]=(char)('0'+x%10);x/=10;}while(n){char s[2]={t[--n],0};if(!ascii_append(out,cap,p,s))return 0;}return 1;}
int experience_build_context_utf8(const StorageContext* st,const FundRecord* fund,char* out,int cap,int* used){ExperienceRecord rows[EXPERIENCE_INJECT_MAX];int n,i,p=0;if(used)*used=0;if(!out||cap<8){return 0;}out[0]=0;n=experience_search(st,fund,rows,EXPERIENCE_INJECT_MAX);if(!ascii_append(out,cap,&p,"["))return 0;for(i=0;i<n;i++){if(i&&!ascii_append(out,cap,&p,","))return 0;if(!ascii_append(out,cap,&p,"{\"type\":\""))return 0;if(!ascii_append(out,cap,&p,rows[i].experience_type==EXPERIENCE_TYPE_SUCCESS?"SUCCESS":(rows[i].experience_type==EXPERIENCE_TYPE_FAILURE?"FAILURE":"CAUTION")))return 0;if(!ascii_append(out,cap,&p,"\",\"score\":"))return 0;if(!int_append(out,cap,&p,rows[i].score))return 0;if(!ascii_append(out,cap,&p,",\"lesson\":\""))return 0;if(!utf8_append_w(out,cap,&p,(WCHAR*)rows[i].lesson))return 0;if(!ascii_append(out,cap,&p,"\",\"rule\":\""))return 0;if(!utf8_append_w(out,cap,&p,(WCHAR*)rows[i].reusable_rule))return 0;if(!ascii_append(out,cap,&p,"\"}"))return 0;}if(!ascii_append(out,cap,&p,"]"))return 0;if(used)*used=n;return 1;}

const WCHAR* experience_type_name(int type){if(type==EXPERIENCE_TYPE_SUCCESS)return L"成功经验";if(type==EXPERIENCE_TYPE_FAILURE)return L"失败经验";return L"谨慎经验";}
const WCHAR* experience_status_name(int status){if(status==EXPERIENCE_STATUS_ACTIVE)return L"有效";if(status==EXPERIENCE_STATUS_OBSERVE)return L"观察";return L"停用";}
